:root {
  --card-bg: #fff8f0;
  --card-border: #f4a94e;
  --header-bg: #f4a94e;
  --header-text: #ffffff;
  --title-color: #7a3e00;
  --label-color: #a05c10;
  --value-bg: #fff3e0;
  --value-text: #d45f00;
  --tag-skin-bg: #fde8d8;
  --tag-skin-text: #c05000;
  --tag-activity-bg: #d4f0e8;
  --tag-activity-text: #1a7a55;
  --tag-uv-bg: #ffe0e0;
  --tag-uv-text: #b52020;
  --footer-bg: #fde8c0;
  --footer-text: #8a4a00;
}

.spf-card {
  background-color: var(--card-bg);
  border: 2px solid var(--card-border);
  border-radius: 16px;
  width: 280px;
  padding: 0;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  gap: 0;
}

.spf-header {
  background-color: var(--header-bg);
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px 16px;
}

.spf-icon {
  font-size: 24px;
  line-height: 1;
}

.spf-title {
  font-size: 18px;
  font-weight: 700;
  color: var(--header-text);
  margin: 0;
}

.spf-level {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 16px;
}

.spf-label {
  font-size: 13px;
  font-weight: 600;
  color: var(--label-color);
}

.spf-value {
  font-size: 20px;
  font-weight: 800;
  color: var(--value-text);
  background-color: var(--value-bg);
  border-radius: 8px;
  padding: 4px 12px;
}

.spf-tags {
  display: flex;
  flex-direction: row;
  gap: 8px;
  padding: 0 16px 14px 16px;
}

.tag {
  font-size: 12px;
  font-weight: 600;
  border-radius: 20px;
  padding: 4px 10px;
}

.tag-skin {
  background-color: var(--tag-skin-bg);
  color: var(--tag-skin-text);
}

.tag-activity {
  background-color: var(--tag-activity-bg);
  color: var(--tag-activity-text);
}

.tag-uv {
  background-color: var(--tag-uv-bg);
  color: var(--tag-uv-text);
}

.spf-footer {
  background-color: var(--footer-bg);
  color: var(--footer-text);
  font-size: 13px;
  font-weight: 600;
  text-align: center;
  padding: 10px 16px;
}
